    int left = 0, right = static_cast<int>(a.size());
    while (left < right) {
        int mid = left + (right - left) / 2;
        if (a[mid] < x) left = mid + 1;
        else right = mid;
    }
    optional<int> floorValue, ceilValue;
    if (left < static_cast<int>(a.size())) ceilValue = a[left];
    if (left < static_cast<int>(a.size()) && a[left] == x) floorValue = x;
    else if (left > 0) floorValue = a[left - 1];
    return {floorValue, ceilValue};
}

