pair<int, int> firstLastOccurrence(const vector<int>& a, int x) {
    auto bound = [&](bool strict) {
        int left = 0, right = static_cast<int>(a.size());
        while (left < right) {
            int mid = left + (right - left) / 2;
            if (strict ? a[mid] <= x : a[mid] < x) left = mid + 1;
            else right = mid;
        }
        return left;
    };
    int first = bound(false);
    if (first == static_cast<int>(a.size()) || a[first] != x) return {-1, -1};
    return {first, bound(true) - 1};
}

