    int left = 0, right = static_cast<int>(a.size()) - 1;
    while (left <= right) {
        int mid = left + (right - left) / 2;
        if (a[mid] == x) return mid;
        if (a[left] <= a[mid]) {
            if (a[left] <= x && x < a[mid]) right = mid - 1;
            else left = mid + 1;
