bool searchRotatedDuplicates(const vector<int>& a, int x) {
    int left = 0, right = static_cast<int>(a.size()) - 1;
    while (left <= right) {
        int mid = left + (right - left) / 2;
        if (a[mid] == x) return true;
        if (a[left] == a[mid] && a[mid] == a[right]) {
            ++left;
            --right;
        } else if (a[left] <= a[mid]) {
            if (a[left] <= x && x < a[mid]) right = mid - 1;
            else left = mid + 1;
        } else {
            if (a[mid] < x && x <= a[right]) left = mid + 1;
            else right = mid - 1;
        }
    }
    return false;
}

