long long integerSquareRoot(long long n) {
    if (n < 0) throw invalid_argument("square root needs nonnegative n");
    long long left = 1, right = n, answer = 0;
    while (left <= right) {
        long long mid = left + (right - left) / 2;
        if (mid <= n / mid) { answer = mid; left = mid + 1; }
        else right = mid - 1;
    }
    return answer;
}

