int exactIntegerNthRoot(int degree, int m) {
    if (degree <= 0 || m < 0) throw invalid_argument("degree > 0 and m >= 0 required");
    if (m == 0) return 0;
    int left = 1, right = m;
    while (left <= right) {
        int mid = left + (right - left) / 2;
        long long power = 1;
        for (int i = 0; i < degree; ++i) {
            if (power > m / mid) { power = static_cast<long long>(m) + 1; break; }
            power *= mid;
        }
        if (power == m) return mid;
        if (power < m) left = mid + 1;
        else right = mid - 1;
    }
    return -1;
}

