    if (right == 0) return 0;
    int answer = -1;
    while (left <= right) {
        int speed = left + (right - left) / 2;
        long long needed = 0;
        for (int pile : piles) needed += (pile + static_cast<long long>(speed) - 1) / speed;
        if (needed <= hours) { answer = speed; right = speed - 1; }
        else left = speed + 1;
    }
    return answer;
}

