int minDaysForBouquets(const vector<int>& bloom, int bouquets, int flowersPerBouquet) {
    if (bouquets <= 0) return 0;
    if (flowersPerBouquet <= 0 || 1LL * bouquets * flowersPerBouquet > static_cast<long long>(bloom.size())) return -1;
    int left = *min_element(bloom.begin(), bloom.end());
    int right = *max_element(bloom.begin(), bloom.end());
    while (left < right) {
        int day = left + (right - left) / 2;
        int made = 0, run = 0;
        for (int b : bloom) {
            if (b <= day) {
                if (++run == flowersPerBouquet) { ++made; run = 0; }
            } else run = 0;
        }
        if (made >= bouquets) right = day;
        else left = day + 1;
    }
    return left;
}

