    if (weights.empty()) return 0;
    if (days <= 0) return -1;
    long long left = *max_element(weights.begin(), weights.end());
    long long right = accumulate(weights.begin(), weights.end(), 0LL);
    while (left < right) {
        long long cap = left + (right - left) / 2;
        int used = 1;
        long long load = 0;
        for (int weight : weights) {
            if (load + weight > cap) { ++used; load = 0; }
            load += weight;
        }
        if (used <= days) right = cap;
        else left = cap + 1;
    }
    return left;
}

