int maxMinimumCowDistance(vector<int> stalls, int cows) {
    if (cows <= 1) return 0;
    if (cows > static_cast<int>(stalls.size())) return -1;
    sort(stalls.begin(), stalls.end());
    int left = 0, right = stalls.back() - stalls.front();
    while (left < right) {
        int gap = left + (right - left + 1) / 2;
        int placed = 1, last = stalls.front();
        for (size_t i = 1; i < stalls.size(); ++i) {
            if (stalls[i] - last >= gap) { ++placed; last = stalls[i]; }
        }
        if (placed >= cows) left = gap;
        else right = gap - 1;
    }
    return left;
}

