double minimizeMaxGasGap(const vector<int>& stations, int extra) {
    if (stations.size() < 2) return 0.0;
    double left = 0.0, right = 0.0;
    for (size_t i = 1; i < stations.size(); ++i)
        right = max(right, static_cast<double>(stations[i] - stations[i - 1]));
    if (right == 0.0) return 0.0;
    for (int iteration = 0; iteration < 60; ++iteration) {
        double gapLimit = (left + right) / 2.0;
        long long needed = 0;
        for (size_t i = 1; i < stations.size(); ++i) {
            double gap = static_cast<double>(stations[i] - stations[i - 1]);
            needed += static_cast<long long>(ceil(gap / gapLimit)) - 1;
            if (needed > extra) break;
        }
        if (needed <= extra) right = gapLimit;
        else left = gapLimit;
    }
    return right;
}

