double medianSortedArrays(const vector<int>& a, const vector<int>& b) {
    if (a.size() > b.size()) return medianSortedArrays(b, a);
    int n = a.size(), m = b.size();
    if (n + m == 0) throw invalid_argument("both arrays are empty");
    int leftSize = (n + m + 1) / 2;
    int low = 0, high = n;
    while (low <= high) {
        int takeA = low + (high - low) / 2, takeB = leftSize - takeA;
        int aLeft = takeA ? a[takeA - 1] : INT_MIN;
        int aRight = takeA < n ? a[takeA] : INT_MAX;
        int bLeft = takeB ? b[takeB - 1] : INT_MIN;
        int bRight = takeB < m ? b[takeB] : INT_MAX;
        if (aLeft <= bRight && bLeft <= aRight) {
            if ((n + m) & 1) return max(aLeft, bLeft);
            return (static_cast<long long>(max(aLeft, bLeft)) + min(aRight, bRight)) / 2.0;
        }
        if (aLeft > bRight) high = takeA - 1;
        else low = takeA + 1;
    }
    throw invalid_argument("inputs must be sorted");
}

