int kthOfTwoSorted(const vector<int>& a, const vector<int>& b, int k) {
    if (a.size() > b.size()) return kthOfTwoSorted(b, a, k);
    int n = a.size(), m = b.size();
    if (k < 1 || k > n + m) throw out_of_range("k is one-based");
    int low = max(0, k - m), high = min(k, n);
    while (low <= high) {
        int takeA = low + (high - low) / 2, takeB = k - takeA;
        int aLeft = takeA ? a[takeA - 1] : INT_MIN;
        int aRight = takeA < n ? a[takeA] : INT_MAX;
        int bLeft = takeB ? b[takeB - 1] : INT_MIN;
        int bRight = takeB < m ? b[takeB] : INT_MAX;
        if (aLeft <= bRight && bLeft <= aRight) return max(aLeft, bLeft);
        if (aLeft > bRight) high = takeA - 1;
        else low = takeA + 1;
    }
    throw invalid_argument("inputs must be sorted");
}

