int rowWithMostOnes(const vector<vector<int>>& matrix) {
    int bestRow = -1, bestCount = 0;
    for (int r = 0; r < static_cast<int>(matrix.size()); ++r) {
        const auto& row = matrix[r];
        int left = 0, right = row.size();
        while (left < right) {
            int mid = left + (right - left) / 2;
            if (row[mid] == 0) left = mid + 1;
            else right = mid;
        }
        int count = static_cast<int>(row.size()) - left;
        if (count > bestCount) { bestCount = count; bestRow = r; }
    }
    return bestRow;
}

