int medianRowSortedMatrix(const vector<vector<int>>& matrix) {
    if (matrix.empty() || matrix[0].empty()) throw invalid_argument("empty matrix");
    int rows = matrix.size(), cols = matrix[0].size();
    int minimum = INT_MAX, maximum = INT_MIN;
    for (const auto& row : matrix) {
        minimum = min(minimum, row.front());
        maximum = max(maximum, row.back());
    }
    long long left = minimum, right = maximum;
    long long half = 1LL * rows * cols / 2;
    while (left < right) {
        long long mid = left + (right - left) / 2;
        long long count = 0;
        for (const auto& row : matrix)
            count += upper_bound(row.begin(), row.end(), static_cast<int>(mid)) - row.begin();
        if (count > half) right = mid;
        else left = mid + 1;
    }
    return static_cast<int>(left);
}
